            for x, y in positions:
                if group_id not in counts:
                    counts[group_id] = set()
                counts[group_id].add((x // 2, y // 2))
        return all(len(counts[group_id]) == 1 for group_id in counts)

    if not can_form_power():
        return "No solution"

    power_size = len(groups)
    if power_size > 5:
        return "No solution"

    result = [['.' for _ in range(w)] for _ in range(h)]
    for group_id, positions in groups:
        x, y = min(positions)[0], min(positions)[1]
        for pos in positions:
            result[pos[0] - x][pos[1] - y] = str(group_id)

    return '\n'.join([''.join(row) for row in result])

