from collections import deque

def find_polyomino(matrix, h, w):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    def bfs(start_x, start_y):
        queue = deque([(start_x, start_y)])
        visited = set()
        component = []

        while queue:
            x, y = queue.popleft()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            component.append((x, y))

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and matrix[nx][ny] == 'X' and (nx, ny) not in visited:
                    queue.append((nx, ny))

        return component

    components = []
    for i in range(h):
        for j in range(w):
            if matrix[i][j] == 'X':
                component = bfs(i, j)
                if component:
                    components.append(component)

    if len(components) % 2 != 0:
        return "No solution"

    num_components = len(components) // 2
    power = 1
    for comp1, comp2 in zip(components[::2], components[1::2]):
        if len(comp1) != len(comp2):
            return "No solution"

        mapping = {}
        used_numbers = set()

        for ((x1, y1), (x2, y2)) in zip(comp1, comp2):
            if (x1, y1) in mapping and mapping[(x1, y1)] != (x2, y2):
                return "No solution"
            if (x2, y2) in used_numbers:
                return "No solution"
            mapping[(x1, y1)] = (x2, y2)
            used_numbers.add((x2, y2))

        for x, y in comp1:
            matrix[x][y] = str(power)
        for x, y in comp2:
            matrix[x][y] = str(power)
        power += 1

    return '\n'.join(''.join(row) for row in matrix)

