    grid = [stdin.readline().strip() for _ in range(h)]

    def find_polyominoes(grid):
        def dfs(x, y, dx, dy, size, visited, polyomino):
            if x < 0 or x >= h or y < 0 or y >= w or (x, y) in visited or grid[x][y] == '.':
                return False
            if len(polyomino) == size:
                return True
            visited.add((x, y))
            found = dfs(x + dx, y + dy, dx, dy, size, visited, polyomino + [(x, y)])
            visited.remove((x, y))
            return found

        for i in range(h):
            for j in range(w):
                if grid[i][j] == 'X':
                    for k in range(1, min(h*w//2, 6)):
                        visited = set()
                        polyomino = []
                        if dfs(i, j, 0, 1, k, visited, polyomino):  # Downwards
                            yield k, polyomino
                        if dfs(i, j, 1, 0, k, visited, polyomino):  # Rightwards
                            yield k, polyomino

    def place_polyominoes(grid, polyominoes, k):
        used = {}
        def can_place(x, y, p):
            for px, py in p:
                nx, ny = x + px, y + py
                if nx < 0 or nx >= h or ny < 0 or ny >= w or grid[nx][ny] != '.':
                    return False
            return True

        def place(x, y, p, idx):
            for px, py in p:
                nx, ny = x + px, y + py
                grid[nx] = grid[nx][:ny] + str(idx+1) + grid[nx][ny+1:]

        def backtrack(idx):
            if idx == len(polyominoes):
                return True
            k, polyomino = polyominoes[idx]
            if k not in used:
                used[k] = []
            for pos in used[k]:
