                    place(pos[0], pos[1], polyomino, idx)
                    if backtrack(idx + 1):
                        return True
                    place(pos[0], pos[1], polyomino, -1)
            used[k].append((x, y))
            return backtrack(idx + 1)

        for k, polyomino in polyominoes:
            used[k] = []
        for x in range(h):
            for y in range(w):
                if grid[x][y] == '.':
                    placed = False
                    for k, polyomino in polyominoes:
                        if can_place(x, y, polyomino):
                            place(x, y, polyomino, 0)
                            placed = True
                            break
                    if not placed:
                        return None
        return grid

    polyominoes = list(find_polyominoes(grid))
    for k in range(2, 6):
        groups = [[] for _ in range(k)]
        for size, polyomino in polyominoes:
            groups[size % k].append((size, polyomino))
        if all(groups[i]) for i in range(k)):
            result = place_polyominoes(grid.copy(), polyominoes, k)
            if result:
                for row in result:
                    stdout.write(row + '\n')
                return
    stdout.write("No solution\n")

