def find_polyomino_power(h, w, grid):
    def dfs(x, y, c, dx, dy):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            grid[cx][cy] = str(c)
            for nx, ny in ((cx + dx, cy + dy), (cx - dx, cy - dy)):
                if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 'X':
                    stack.append((nx, ny))

    def find_factors():
        factors = []
        for i in range(2, 6):
            found = False
            for x in range(h):
                for y in range(w):
                    if grid[x][y] == 'X':
                        count = sum(grid[a][b] == 'X' for a in range(x, h, i) for b in range(y, w, i))
                        if count == i * i:
                            found = True
                            dfs(x, y, len(factors) + 1, 1 if i > 1 else 0, 0 if i > 1 else 1)
                            break
                if found:
                    break
            if found:
                factors.append(i * i)
            else:
                return "No solution"
        return factors

    factors = find_factors()
    for f in factors:
        for i in range(h):
            for j in range(w):
                if grid[i][j] == '.':
                    grid[i][j] = str(int(factors[-1]) // f)
    return '\n'.join(''.join(row) for row in grid)

